            fresh
                .commit_completion_recovery(
                    stage,
                    CompletionRecoveryDurableReceipt {
                        checkpoint_sha256: checkpoint.digest().unwrap()
                    },
                    &cancel
                )
                .await,
            Err(Error::Crypto)
        ));
        assert!(peer.state.lock().unwrap().persists.is_empty());
    })
    .await
}
